+    public void execute() {
+        getWorkerExecutor().noIsolation().submit(HistoricalFeaturesMetadataWorkAction.class, params -> {
+            params.getClasspath().setFrom(getClasspath());
+            params.getOutputFile().set(getOutputFile());
+        });
